-- Owner/team fixtures and supplied decimal values, never genuine project evidence.
begin;
create function pg_temp.check_true(value boolean,label text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end; $$;
insert into auth.users(id,email,created_at,updated_at,aud,role,is_anonymous)
  select ('82000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'project-fixture-'||n||'@example.test',now(),now(),'authenticated','authenticated',false from generate_series(1,4) n;
insert into auth.sessions(id,user_id,created_at,updated_at)
  select ('82000000-0000-4000-8000-'||lpad((n+10)::text,12,'0'))::uuid,('82000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,now(),now() from generate_series(1,4) n;
do $$ declare a jsonb; b jsonb; c jsonb; d jsonb; p1 uuid; p2 uuid; p3 uuid; invited jsonb; transfer jsonb; r jsonb;
  owner1 uuid; owner2 uuid; foreman uuid; pm uuid; invite_id uuid;
begin
  a := public.account_browser_session('82000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000011',repeat('a',64),'Owner One'); owner1 := (a->>'profile_id')::uuid;
  b := public.account_browser_session('82000000-0000-4000-8000-000000000002','82000000-0000-4000-8000-000000000012',repeat('b',64),'Owner Two'); owner2 := (b->>'profile_id')::uuid;
  c := public.account_browser_session('82000000-0000-4000-8000-000000000003','82000000-0000-4000-8000-000000000013',repeat('c',64),'Invited Foreman'); foreman := (c->>'profile_id')::uuid;
  d := public.account_browser_session('82000000-0000-4000-8000-000000000004','82000000-0000-4000-8000-000000000014',repeat('d',64),'Invited PM'); pm := (d->>'profile_id')::uuid;
  p1 := (public.account_create_project(repeat('a',64),'Fixture A','Fixture client','Fixture location','0','NGN','Africa/Lagos')->>'id')::uuid;
  p2 := (public.account_create_project(repeat('b',64),'Fixture B','Fixture client','Fixture location','0','USD','America/New_York')->>'id')::uuid;
  p3 := (public.account_create_project(repeat('b',64),'Exact decimal fixture','Fixture client','Fixture location','0.123','KWD','Asia/Kuwait')->>'id')::uuid;
  set constraints all immediate;
  perform pg_temp.check_true((public.account_project_access(repeat('a',64),p1)->>'owner')::boolean,'Creator is owner and PM');
  perform pg_temp.check_true(public.account_project_access(repeat('a',64),p2) is null,'Independent owners have no cross-project access');
  perform pg_temp.check_true(public.account_project_access(repeat('c',64),p1) is null,'Known project ID does not grant stranger access');
  perform pg_temp.check_true((select contract_sum=0.123 from public.projects where id=p3),'Foreign supplied decimals remain exact');
  perform pg_temp.check_true((select count(*)=0 from public.boq_items where project_id in (p1,p2,p3)),'New projects receive no invented or converted demo rates');
  invited := public.account_invite(repeat('a',64),p1,'project-fixture-3@example.test','foreman',repeat('e',64)); invite_id := (invited->>'id')::uuid;
  perform pg_temp.check_true(public.account_accept_invite(repeat('c',64),repeat('e',64))->>'error'='verify_email','Unproved signup email cannot accept invite');
  perform public.account_verified_email(repeat('c',64),'82000000-0000-4000-8000-000000000003','82000000-0000-4000-8000-000000000013');
  perform public.account_verified_email(repeat('a',64),'82000000-0000-4000-8000-000000000001','82000000-0000-4000-8000-000000000011');
  perform public.account_verified_email(repeat('d',64),'82000000-0000-4000-8000-000000000004','82000000-0000-4000-8000-000000000014');
  perform pg_temp.check_true(public.account_accept_invite(repeat('d',64),repeat('e',64))->>'error'='unavailable','Forwarded invite cannot grant another verified email access');
  r := public.account_accept_invite(repeat('c',64),repeat('e',64));
  perform pg_temp.check_true(r->>'role'='foreman','Owner chooses invitee role');
  perform pg_temp.check_true(public.account_accept_invite(repeat('c',64),repeat('e',64))->>'error'='unavailable','Invite replay denied');
  perform pg_temp.check_true(public.account_manage_member(repeat('c',64),p1,foreman,'pm',false)->>'error'='unavailable','Foreman cannot self-promote');
  r:=public.account_team(repeat('c',64),p1);
  perform pg_temp.check_true(jsonb_array_length(r->'members')=2 and r->'invitations'='[]'::jsonb and r->'events'='[]'::jsonb,'Foreman can see the team roster without private invitations or audit events');
  invited := public.account_invite(repeat('a',64),p1,'project-fixture-4@example.test','pm',repeat('f',64));
  perform public.account_cancel_invite(repeat('a',64),p1,(invited->>'id')::uuid);
  perform pg_temp.check_true(public.account_accept_invite(repeat('d',64),repeat('f',64))->>'error'='unavailable','Cancelled invitation denied');
  invited := public.account_invite(repeat('a',64),p1,'project-fixture-4@example.test','pm',repeat('1',64));
  update public.account_invitations set expires_at=now()-interval '1 second' where id=(invited->>'id')::uuid;
  perform pg_temp.check_true(public.account_accept_invite(repeat('d',64),repeat('1',64))->>'error'='unavailable','Expired invitation denied');
  invited := public.account_invite(repeat('a',64),p1,'project-fixture-4@example.test','pm',repeat('2',64));
  perform public.account_accept_invite(repeat('d',64),repeat('2',64));
  perform pg_temp.check_true(public.account_project_access(repeat('d',64),p1)->>'role'='pm','Invited PM has review role');
  perform pg_temp.check_true(public.account_invite(repeat('d',64),p1,'stranger@example.test','pm',repeat('3',64))->>'error'='unavailable','PM review rights do not grant ownership administration');
  invited := public.account_invite(repeat('b',64),p2,'project-fixture-1@example.test','foreman',repeat('4',64));
  perform public.account_accept_invite(repeat('a',64),repeat('4',64));
  perform pg_temp.check_true(public.account_project_access(repeat('a',64),p1)->>'role'='pm' and public.account_project_access(repeat('a',64),p2)->>'role'='foreman','One person has independent project roles');
  perform pg_temp.check_true(public.account_invite(repeat('a',64),p2,'stranger@example.test','pm',repeat('5',64))->>'error'='unavailable','Role on one project cannot administer another');
  perform public.account_select_project(repeat('c',64),p1);
  perform public.account_manage_member(repeat('a',64),p1,foreman,null,true);
  perform pg_temp.check_true(public.account_project_access(repeat('c',64),p1) is null,'Membership revocation immediately denies old session');
  perform pg_temp.check_true(public.account_list_projects(repeat('c',64))->'projects'='[]'::jsonb,'Removed membership no longer lists project');
  perform pg_temp.check_true(public.account_list_projects(repeat('c',64))->>'active_project_id' is null,'Removal clears the visible selection without silently choosing another project');
  perform public.account_manage_member(repeat('a',64),p1,pm,'foreman',false);
  perform pg_temp.check_true(public.account_project_access(repeat('d',64),p1)->>'role'='foreman','Downgrade immediately changes authority');
  perform pg_temp.check_true(public.account_manage_member(repeat('a',64),p1,owner1,'foreman',false)->>'error'='owner_transfer_required','Current owner cannot be downgraded');
  begin update public.account_memberships set active=false,revoked_at=now() where project_id=p1 and profile_id=owner1; raise exception 'Owner removal unexpectedly passed';
  exception when raise_exception then if sqlerrm<>'A project must retain one active owner with the PM role' then raise; end if; end;
  invited := public.account_invite(repeat('a',64),p1,'project-fixture-3@example.test','foreman',repeat('6',64));
  transfer := public.account_start_transfer(repeat('a',64),p1,pm);
  perform pg_temp.check_true((select owner_profile_id=owner1 from public.account_projects where project_id=p1),'Requested transfer leaves old owner active');
  perform pg_temp.check_true(public.account_accept_transfer(repeat('b',64),p1,(transfer->>'id')::uuid)->>'error'='unavailable','Unrelated account cannot accept ownership');
  r := public.account_accept_transfer(repeat('d',64),p1,(transfer->>'id')::uuid);
  perform pg_temp.check_true((r->>'owner')::boolean and r->>'role'='pm','Existing member accepts ownership and becomes PM');
  perform pg_temp.check_true(not (public.account_project_access(repeat('a',64),p1)->>'owner')::boolean,'Old owner loses administration immediately');
  perform pg_temp.check_true(public.account_accept_transfer(repeat('d',64),p1,(transfer->>'id')::uuid)->>'error'='unavailable','Ownership acceptance is single-use');
  perform pg_temp.check_true(public.account_accept_invite(repeat('c',64),repeat('6',64))->>'error'='unavailable','Invitation rechecks issuing owner authority after transfer');
  perform public.account_archive_project(repeat('d',64),p1,true);
  perform pg_temp.check_true(public.account_project_access(repeat('a',64),p1) is not null,'Archive preserves authorized read access');
  perform pg_temp.check_true(public.account_project_access(repeat('a',64),p1,true)->>'error'='archived','Archive blocks work mutations');
  perform pg_temp.check_true(public.account_invite(repeat('d',64),p1,'stranger@example.test','foreman',repeat('7',64))->>'error'='archived','Archive blocks invitations');
  perform public.account_manage_member(repeat('d',64),p1,owner1,null,true);
  perform pg_temp.check_true(public.account_project_access(repeat('a',64),p1) is null,'Archived project still allows owner to revoke former member');
  perform public.account_archive_project(repeat('d',64),p1,false);
  perform pg_temp.check_true(public.account_project_access(repeat('d',64),p1,true)->>'error' is null,'Owner can restore project');
  perform pg_temp.check_true(public.account_team(repeat('a',64),p1) is null,'Former member cannot read retained admin audit');
  begin update public.account_projects set currency='USD' where project_id=p1; raise exception 'Currency relabel unexpectedly passed'; exception when raise_exception then if sqlerrm<>'Project currency and timezone cannot relabel captured evidence' then raise; end if; end;
  begin delete from public.account_project_events where project_id=p1; raise exception 'Audit deletion unexpectedly passed'; exception when raise_exception then if sqlerrm<>'Account evidence is append-only' then raise; end if; end;
end $$;
set local role authenticated;
do $$ begin
  begin perform 1 from public.account_memberships; raise exception 'Browser team read unexpectedly passed'; exception when insufficient_privilege then null; end;
  begin perform public.account_create_project(repeat('a',64),'Injected','Injected','Injected','0','NGN','Africa/Lagos'); raise exception 'Browser service RPC unexpectedly passed'; exception when insufficient_privilege then null; end;
end $$;
reset role;
rollback;
